#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

# The palette is the wizard library's, whole. `RED` has no caller in these stages, and it stays
# anyway rather than making this copy diverge from the template every wizard is generated from.
# shellcheck disable=SC2034
if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — point the Solver at a CTFd board and prove it can reach it.
# ──────────────────────────────────────────────────────────────────────────

cd "$(dirname "${BASH_SOURCE[0]}")/.."

# clear_env KEY — drop KEY from ENV_FILE entirely. The library's write_env can set a value
# but not remove one, and for the auth variables an empty leftover is as harmful as a wrong
# value: whichever exists first wins the SDK's credential search, so a blank line shadows
# the credential the human just pasted.
clear_env() {
  [[ -f "$ENV_FILE" ]] || return 0
  grep -qE "^${1}=" "$ENV_FILE" || return 0
  local tmp; tmp=$(mktemp)
  grep -vE "^${1}=" "$ENV_FILE" > "$tmp" || true
  mv "$tmp" "$ENV_FILE"
  printf '  %s✓ removed%s %s from %s\n' "$GREEN" "$RESET" "$1" "$ENV_FILE"
}

TOTAL_STAGES=7

banner "Point the Solver at a CTF board"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Which board"
say "One value decides which competition the Solver enters."
warn "BrunnerCTF runs two platforms. Global permits AI. The Danish one bans it outright."
note "Entering an agent on the Danish platform is a disqualification, not a misconfiguration."
say ""
say "Default is BrunnerCTF Global. Press Enter to take it."
ask CTFD_URL "Board URL [https://global.brunnerctf.dk]:"
CTFD_URL="${CTFD_URL:-https://global.brunnerctf.dk}"
CTFD_URL="${CTFD_URL%/}"
case "$CTFD_URL" in
  *danmark.brunnerctf.dk*)
    warn "That is the no-AI Danish platform."
    confirm "Point the Solver there anyway?" || { say "Stopping. Re-run and take the default."; exit 1; } ;;
esac
write_env CTFD_URL "$CTFD_URL"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the account"
say "You have to do this part — account creation is yours, not the agent's."
open_url "$CTFD_URL/register"
step "Register a user. Any handle; nothing political or discriminatory (board rules)."
step "Check your inbox and click the confirmation link — an unconfirmed account cannot play."
note "One account and one team only. A second identity is a bannable rule violation."
pause "Registered and email confirmed?"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the team"
say "This board scores teams, so a user on its own cannot submit."
open_url "$CTFD_URL/teams/new"
step "Create the team, or join the existing one with its password if a teammate made it."
note "No size limit — everyone playing joins the same team."
pause "On a team?"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Mint the API token"
say "This is what the Solver authenticates with. It is shown exactly once."
open_url "$CTFD_URL/settings#tokens"
step "Settings -> Access Tokens -> Generate."
step "Set an expiry past the end of the event, then copy the token."
warn "Paste it below and nowhere else — not into a commit, not into a chat window."
ask_secret CTFD_API_TOKEN "Paste the access token:"
[ -n "$CTFD_API_TOKEN" ] || { warn "no token entered — the probe cannot run without one"; }
write_env CTFD_API_TOKEN "$CTFD_API_TOKEN"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Name this Run"
say "The Solver refuses to mint this for itself, and a restart is the reason: the Run's"
say "absolute deadline is stamped under /state/runs/<RUN_ID>, and it is consulted only"
say "when there is no window there already. A fresh id on every boot would hand a"
say "restarted Solver a fresh window, silently, with nobody there to see it."
note "One path component. Reuse it to rejoin a Run; change it to start a new one."
ask RUN_ID "A name for this Run (e.g. brunner-practice-1):"
[ -n "$RUN_ID" ] || warn "no name entered — the Solver will refuse to start without one"
write_env RUN_ID "$RUN_ID"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "How the Solver pays for inference"
say "Practice runs go on the subscription: no per-token cost, but a quota that hard-stops"
say "until it resets. Competition day goes on a metered key: it costs money and never"
say "hits a cliff mid-run."
say ""
warn "Exactly one of these may be set. An empty leftover still shadows the other, and"
warn "setting both makes the SDK send two auth headers, which the API rejects outright."
say ""
if confirm "Practice run on the subscription? (No = metered key for competition day.)"; then
  step "In another terminal, run:  claude setup-token"
  step "Complete the browser login it opens, then copy the token it prints."
  ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the token (sk-ant-oat01-...):"
  if [ -n "$CLAUDE_CODE_OAUTH_TOKEN" ]; then
    write_env CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"
    clear_env ANTHROPIC_API_KEY
    clear_env ANTHROPIC_AUTH_TOKEN
  else
    note "left as-is"
  fi
else
  open_url "https://console.anthropic.com/settings/keys"
  step "API keys -> Create key -> copy it."
  ask_secret ANTHROPIC_API_KEY "Paste the metered API key (sk-ant-api03-...):"
  if [ -n "$ANTHROPIC_API_KEY" ]; then
    write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
    clear_env CLAUDE_CODE_OAUTH_TOKEN
    clear_env ANTHROPIC_AUTH_TOKEN
  else
    note "left as-is"
  fi
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Prove it works"
say "Two checks, both against the live board."
say ""
step "Rules drift — has anything in the rulebook changed since we snapshotted it?"
case "$CTFD_URL" in
  *global.brunnerctf.dk*) rules_baseline=docs/competitions/brunnerctf-2026-global.rules.txt ;;
  *)                      rules_baseline="" ;;
esac
if [ -n "$rules_baseline" ]; then
  sh scripts/check-rules-drift.sh "$rules_baseline" || \
    warn "read that diff before playing — accept it with --update once you have"
else
  note "no rules baseline snapshotted for this board yet — see docs/competitions/"
fi
say ""
step "API path — can the Solver enumerate, submit, and download?"
note "This submits ONE deliberately wrong flag to read the verdict semantics."
note "One wrong submission is not the brute-forcing the rules ban; a retry loop would be."
if confirm "Run the full probe, including that submission?"; then
  python3 scripts/ctfd_probe.py || SKIPPED+=("re-run: python3 scripts/ctfd_probe.py — a check failed")
else
  python3 scripts/ctfd_probe.py --no-attempt || SKIPPED+=("re-run: python3 scripts/ctfd_probe.py — a check failed")
  SKIPPED+=("verify submission semantics before the event: python3 scripts/ctfd_probe.py")
fi
pause

finish
